use super::*;
struct ClearLog {calls:usize}
fn NIE_clear(bytes:&[u8],log:&mut ClearLog) {assert!(bytes.is_empty());log.calls+=1;}
fn NIE_after_guard(program_id:&Pubkey,accounts:&[AccountInfo<'_>],instruction_data:&[u8],log:&mut ClearLog)->ProgramResult {
    let magic = instruction_data
        .get(..4)
        .ok_or(ProgramError::InvalidInstructionData)?;
    let mut runtime = SolanaPoolCpiRuntimeV1;
    let result = if cfg!(feature = "pair-forest-account-evidence") && magic == b"AS8I" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let rent = Rent::get()?;
            process_pair_forest_initialize_with_runtime_v1(
                program_id,
                accounts,
                instruction_data,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-account-evidence") && magic == b"AS8C" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let rent = Rent::get()?;
            process_pair_forest_checkpoint_with_runtime_v1(
                program_id,
                accounts,
                instruction_data,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-account-evidence") && magic == b"AS8D" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let rent = Rent::get()?;
            process_pair_forest_deposit_with_runtime_v1(
                program_id,
                accounts,
                instruction_data,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-account-evidence") && magic == b"ASQ8" {
        #[cfg(feature = "pair-forest-account-evidence")]
        {
            let slot = Clock::get()?.slot;
            let rent = Rent::get()?;
            process_pair_forest_terminal_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-account-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-forest-full-asf8-audit") && magic == b"ASF8" {
        #[cfg(feature = "pair-forest-full-asf8-audit")]
        {
            let slot = Clock::get()?.slot;
            let rent = Rent::get()?;
            process_pair_forest_terminal_full_asf8_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                &rent,
                &mut runtime,
            )
        }
        #[cfg(not(feature = "pair-forest-full-asf8-audit"))]
        unreachable!()
    } else if magic == POOL_V1_INITIALIZE_INSTRUCTION_MAGIC {
        process_initialize_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            &mut runtime,
            program::set_return_data,
        )
    } else if magic == POOL_V1_DEPOSIT_INSTRUCTION_MAGIC {
        process_deposit_with_runtime_v1(program_id, accounts, instruction_data, &mut runtime)
    } else if magic == POOL_V1_PREPARE_SETTLEMENT_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        let rent = Rent::get()?;
        process_prepare_settlement_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            &rent,
            solana_sha256,
            &mut runtime,
        )
    } else if magic == POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_MAGIC {
        process_cancel_prepared_settlement_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            solana_sha256,
            &mut runtime,
            program::set_return_data,
        )
    } else if magic == POOL_V1_SETTLE_PREPARED_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        let rent = Rent::get()?;
        process_settle_prepared_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            &rent,
            solana_sha256,
            &mut runtime,
            program::set_return_data,
        )
    } else if cfg!(feature = "pair-afterstate-evidence")
        && magic == crate::instruction::POOL_V1_PAIR_PRIVATE_TRANSFER_INSTRUCTION_MAGIC
    {
        #[cfg(feature = "pair-afterstate-evidence")]
        {
            let slot = Clock::get()?.slot;
            process_pair_private_transfer_with_verifier_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                solana_sha256,
                dispatch_pair_verified_afterstate_readonly_v1,
                program::set_return_data,
            )
        }
        #[cfg(not(feature = "pair-afterstate-evidence"))]
        unreachable!()
    } else if cfg!(feature = "pair-afterstate-evidence")
        && magic == crate::instruction::POOL_V1_PAIR_WITHDRAWAL_INSTRUCTION_MAGIC
    {
        #[cfg(feature = "pair-afterstate-evidence")]
        {
            let slot = Clock::get()?.slot;
            process_pair_withdrawal_with_verifier_v1(
                program_id,
                accounts,
                instruction_data,
                slot,
                solana_sha256,
                &mut runtime,
                dispatch_pair_verified_afterstate_readonly_v1,
                program::set_return_data,
            )
        }
        #[cfg(not(feature = "pair-afterstate-evidence"))]
        unreachable!()
    } else if magic == POOL_V1_PRIVATE_TRANSFER_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        process_private_transfer_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            solana_sha256,
            &mut runtime,
            dispatch_selected_verifier_v1,
            program::set_return_data,
        )
    } else if magic == POOL_V1_WITHDRAWAL_INSTRUCTION_MAGIC {
        let slot = Clock::get()?.slot;
        process_withdrawal_with_runtime_v1(
            program_id,
            accounts,
            instruction_data,
            slot,
            solana_sha256,
            &mut runtime,
            dispatch_selected_verifier_v1,
            program::set_return_data,
        )
    } else {
        Err(ProgramError::InvalidInstructionData)
    };
    if result.is_err() {
        NIE_clear(&[],log);
    }
    result

}

#[kani::stub(core::ptr::copy_nonoverlapping,crate::NIE_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NIE_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NIE_KMX::KMX_realloc)]
#[kani::proof]
#[kani::unwind(33)]
fn association() {
 let data:[u8;8]=kani::any();let len:usize=kani::any();kani::assume(len<=8);
 if len>=4 {let magic=&data[..4];kani::assume(!(magic == b"AS8I" || magic == b"AS8C" || magic == b"AS8D" || magic == b"ASQ8" || magic == b"ASF8" || magic == POOL_V1_INITIALIZE_INSTRUCTION_MAGIC || magic == POOL_V1_DEPOSIT_INSTRUCTION_MAGIC || magic == POOL_V1_PREPARE_SETTLEMENT_INSTRUCTION_MAGIC || magic == POOL_V1_CANCEL_PREPARED_SETTLEMENT_INSTRUCTION_MAGIC || magic == POOL_V1_SETTLE_PREPARED_INSTRUCTION_MAGIC || magic == POOL_V1_PRIVATE_TRANSFER_INSTRUCTION_MAGIC || magic == POOL_V1_WITHDRAWAL_INSTRUCTION_MAGIC));}
 let program=Pubkey::new_from_array(kani::any());let mut log=ClearLog{calls:0};
 let result=NIE_after_guard(&program,&[],&data[..len],&mut log);
 assert!(result==Err(ProgramError::InvalidInstructionData));
 assert!(log.calls==usize::from(len>=4));
}
